import{_ as l,a0 as d,w as p,s as a,ao as r,I as s,x as i,a1 as o,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"如何在 Linux 中查找文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中查找文件 | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中查找文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中查找文件 | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20180405 How to find files in Linux","title":"如何在 Linux 中查找文件","tag":"201804","desc":""},"relativePath":"201804/20180405 How to find files in Linux.md","filePath":"[post].md"}'),u={name:"201804/20180405 How to find files in Linux.md"};function f(g,e,m,x,h,c){const t=d("Link");return p(),a("div",null,[e[22]||(e[22]=r('<h1 id="如何在-linux-中查找文件" tabindex="-1">如何在 Linux 中查找文件 <a class="header-anchor" href="#如何在-linux-中查找文件" aria-label="Permalink to “如何在 Linux 中查找文件”">​</a></h1><blockquote><p>使用简单的命令在 Linux 下基于类型、内容等快速查找文件。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/find-file-linux-code_magnifying_glass_zero.png?itok=E2HoPDg0" alt=""></p><p>如果你是 Windows 或 OSX 的非资深用户，那么可能使用 GUI 来查找文件。你也可能发现界面受限，令人沮丧，或者两者兼而有之，并学会了组织文件并记住它们的确切顺序。你也可以在 Linux 中做到这一点 —— 但你不必这样做。</p><p>Linux 的好处之一是它提供了多种方式来处理。你可以打开任何文件管理器或按下 <code>Ctrl+F</code>，你也可以使用程序手动打开文件，或者你可以开始输入字母，它会过滤当前目录列表。</p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/uploads/find-files-in-linux-ctrlf.png?itok=1gf9kIut" alt="Screenshot of how to find files in Linux with Ctrl+F" title="Screenshot of how to find files in Linux with Ctrl+F"></p><p><em>使用 Ctrl+F 在 Linux 中查找文件的截图</em></p><p>但是如果你不知道你的文件在哪里，又不想搜索整个磁盘呢？对于这个以及其他各种情况，Linux 都很合适。</p><h3 id="按命令名查找程序位置" tabindex="-1">按命令名查找程序位置 <a class="header-anchor" href="#按命令名查找程序位置" aria-label="Permalink to “按命令名查找程序位置”">​</a></h3><p>如果你习惯随心所欲地放文件，Linux 文件系统看起来会让人望而生畏。对我而言，最难习惯的一件事是找到程序在哪里。</p><p>例如，<code>which bash</code> 通常会返回 <code>/bin/bash</code>，但是如果你下载了一个程序并且它没有出现在你的菜单中，那么 <code>which</code> 命令就是一个很好的工具。</p><p>一个类似的工具是 <code>locate</code> 命令，我发现它对于查找配置文件很有用。我不喜欢输入程序名称，因为像 <code>locate php</code> 这样的简单程序通常会提供很多需要进一步过滤的结果。</p><p>有关 <code>locate</code> 和 <code>which</code> 的更多信息，请参阅 <code>man</code> 页面：</p><ul><li><code>man which</code></li><li><code>man locate</code></li></ul><h3 id="find" tabindex="-1">find <a class="header-anchor" href="#find" aria-label="Permalink to “find”">​</a></h3><p><code>find</code> 工具提供了更先进的功能。以下是我安装在许多服务器上的脚本示例，我用于确保特定模式的文件（也称为 glob）仅存在五天，并且所有早于此的文件都将被删除。 （自上次修改以来，分数用于保留最多 240 分钟的偏差）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find ./backup/core-files*.tar.gz -mtime +4.9 -exec rm {} \\;</span></span></code></pre></div><p><code>find</code> 工具有许多高级用法，但最常见的是对结果执行命令，而不用链式地按照类型、创建日期、修改日期过滤文件。</p><p><code>find</code> 的另一个有趣用处是找到所有有可执行权限的文件。这有助于确保没有人在你昂贵的服务器上安装比特币挖矿程序或僵尸网络。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find / -perm /+x</span></span></code></pre></div><p>有关 <code>find</code> 的更多信息，请使用 <code>man find</code> 参考 <code>man</code> 页面。</p><h3 id="grep" tabindex="-1">grep <a class="header-anchor" href="#grep" aria-label="Permalink to “grep”">​</a></h3><p>想通过内容中查找文件？ Linux 已经实现了。你可以使用许多 Linux 工具来高效搜索符合模式的文件，但是 <code>grep</code> 是我经常使用的工具。</p><p>假设你有一个程序发布代码引用和堆栈跟踪的错误消息。你要在日志中找到这些。 <code>grep</code> 不总是最好的方法，但如果文件是一个给定的值，我经常使用 <code>grep -R</code>。</p><p>越来越多的 IDE 正在实现查找功能，但是如果你正在访问远程系统或出于任何原因没有 GUI，或者如果你想在当前目录递归查找，请使用：<code>grep -R {searchterm} </code> 或在支持 <code>egrep</code> 别名的系统上，只需将 <code>-e</code> 标志添加到命令 <code>egrep -r {regex-pattern}</code>。</p>',25)),s("p",null,[e[2]||(e[2]=i("我在去年给 ",-1)),o(t,{href:"https://www.raspbian.org/"},{default:n(()=>[...e[0]||(e[0]=[i("Raspbian",-1)])]),_:1}),e[3]||(e[3]=i(" 中的 ",-1)),e[4]||(e[4]=s("code",null,"dhcpcd5",-1)),e[5]||(e[5]=i(" 打补丁时使用了这种技术，这样我就可以在",-1)),o(t,{href:"https://www.raspberrypi.org/"},{default:n(()=>[...e[1]||(e[1]=[i("树莓派基金会",-1)])]),_:1}),e[6]||(e[6]=i("发布新的 Debian 时继续操作网络接入点了。",-1))]),e[23]||(e[23]=s("p",null,"哪些提示可帮助你在 Linux 上更有效地搜索文件？",-1)),e[24]||(e[24]=s("hr",null,null,-1)),s("p",null,[e[8]||(e[8]=i("via: ",-1)),o(t,{href:"https://opensource.com/article/18/4/how-find-files-linux"},{default:n(()=>[...e[7]||(e[7]=[i("https://opensource.com/article/18/4/how-find-files-linux",-1)])]),_:1})]),s("p",null,[e[13]||(e[13]=i("作者：",-1)),o(t,{href:"https://opensource.com/users/lewiscowles1986"},{default:n(()=>[...e[9]||(e[9]=[i("Lewis Cowles",-1)])]),_:1}),e[14]||(e[14]=i(" 选题：",-1)),o(t,{href:"https://github.com/lujun9972"},{default:n(()=>[...e[10]||(e[10]=[i("lujun9972",-1)])]),_:1}),e[15]||(e[15]=i(" 译者：",-1)),o(t,{href:"https://github.com/geekpi"},{default:n(()=>[...e[11]||(e[11]=[i("geekpi",-1)])]),_:1}),e[16]||(e[16]=i(" 校对：",-1)),o(t,{href:"https://github.com/wxy"},{default:n(()=>[...e[12]||(e[12]=[i("wxy",-1)])]),_:1})]),s("p",null,[e[19]||(e[19]=i("本文由 ",-1)),o(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[17]||(e[17]=[i("LCTT",-1)])]),_:1}),e[20]||(e[20]=i(" 原创编译，",-1)),o(t,{href:"https://linux.cn/"},{default:n(()=>[...e[18]||(e[18]=[i("Linux中国",-1)])]),_:1}),e[21]||(e[21]=i(" 荣誉推出",-1))])])}const w=l(u,[["render",f]]);export{L as __pageData,w as default};
